Globe projection

maplibre() |&gt;
  set_projection("globe")

動かしてみる

maplibre() |&gt;
  set_projection("globe") |&gt;
  fly_to(
    center = c(141.359719, 43.071776),
    zoom = 18,
    pitch = 75,
    bearing = 136
  )


